@push('scripts')
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js"></script>
<script>
// فونت فارسی Vazirmatn (base64) — کوتاه شده برای نمونه. نسخه کامل را جایگزین کن.
window.VazirmatnFont = "";

function generatePDF(mode) {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({orientation: "portrait", unit: "mm", format: "a5"});
    // افزودن فونت فارسی
    doc.addFileToVFS('Vazirmatn.ttf', window.VazirmatnFont);
    doc.addFont('Vazirmatn.ttf', 'Vazirmatn', 'normal');
    doc.setFont('Vazirmatn');
    doc.setFontSize(12);

    let y = 16;
    doc.text("{{ $shop->name ?? 'نام فروشگاه' }}", 105, y, {align: 'center'});
    y += 7;
    doc.setFontSize(11);
    doc.text("آدرس: {{ $shop->address ?? '-' }}", 105, y, {align:'center'});
    y += 7;
    doc.text("شماره تماس: {{ $shop->phone ?? '-' }}", 105, y, {align:'center'});
    doc.setFontSize(12);

    y += 10;
    doc.text("شماره فاکتور: {{ $sale->invoice_number }}", 140, y, {align:'right'});
    doc.text("تاریخ: {{ isset($sale->issued_at) ? verta($sale->issued_at)->format('Y/m/d H:i') : '-' }}", 10, y, {align:'left'});

    let tableRows = [
        @foreach($sale->items as $index => $item)
            [
                '{{ $index+1 }}',
                '{{ optional($item->product)->barcode ?? '-' }}',
                '{{ optional($item->product)->name ?? '-' }}',
                '{{ $item->description ?? '-' }}',
                '{{ $item->quantity }}',
                '{{ $item->unit ?? '-' }}',
                '{{ number_format($item->unit_price) }}',
                '{{ number_format($item->discount ?? 0) }}',
                '{{ number_format($item->tax ?? 0) }}',
                '{{ number_format($item->total) }}'
            ],
        @endforeach
    ];
    doc.autoTable({
        head: [[
            "ردیف", "کد کالا", "نام کالا/خدمت", "توضیحات", "تعداد", "واحد",
            "قیمت واحد", "تخفیف", "مالیات", "جمع جزء"
        ]],
        body: tableRows,
        startY: y + 8,
        theme: 'grid',
        styles: {font: "Vazirmatn", fontSize: 11, cellPadding: 1.5, halign: 'right'},
        headStyles: {fillColor: "#e3eafc", textColor: "#222", fontStyle: 'bold'},
        bodyStyles: {fillColor: "#fff"},
        alternateRowStyles: {fillColor: "#f5f6fa"},
        margin: {left: 6, right: 6},
        tableWidth: 144,
        styles: {overflow: 'linebreak'}
    });

    if(mode === 'download') {
        doc.save("فاکتور-{{ $sale->invoice_number }}.pdf");
    } else if(mode === 'share') {
        // خروجی blob در jsPDF در نسخه فعلی sync است، نه promise!
        var pdfBlob = doc.output('blob');
        if(window.navigator.canShare && window.navigator.canShare({ files: [new File([pdfBlob], "factor.pdf", {type: "application/pdf"})] })) {
            const file = new File([pdfBlob], "factor.pdf", {type: "application/pdf"});
            window.navigator.share({
                title: "فاکتور شماره {{ $sale->invoice_number }}",
                text: "فاکتور فروش از {{ $shop->name ?? '' }}",
                files: [file]
            });
        } else {
            var link = document.createElement('a');
            link.href = URL.createObjectURL(pdfBlob);
            link.download = "فاکتور-{{ $sale->invoice_number }}.pdf";
            link.click();
            alert("اشتراک فایل PDF فقط روی گوشی و مرورگرهای جدید پشتیبانی می‌شود. لطفاً فایل را دانلود کرده و دستی ارسال کنید.");
        }
    }
}

function shareAsImage() {
    let invoice = document.getElementById('invoice-wrapper');
    html2canvas(invoice, {scale:2}).then(function(canvas){
        canvas.toBlob(function(blob){
            if(window.navigator.canShare && window.navigator.canShare({ files: [new File([blob], "factor.png", {type:"image/png"})] })) {
                const file = new File([blob], "factor.png", {type:"image/png"});
                window.navigator.share({
                    title: "فاکتور شماره {{ $sale->invoice_number }}",
                    text: "فاکتور فروش از {{ $shop->name ?? '' }}",
                    files: [file]
                });
            } else {
                var link = document.createElement('a');
                link.href = URL.createObjectURL(blob);
                link.download = "فاکتور-{{ $sale->invoice_number }}.png";
                link.click();
                alert("اشتراک تصویر فقط روی گوشی و مرورگرهای جدید پشتیبانی می‌شود. لطفاً تصویر را دانلود و دستی ارسال کنید.");
            }
        });
    });
}

// QR
document.addEventListener('DOMContentLoaded', function(){
    let qr = document.getElementById('invoice-qr');
    if(qr){
        new QRCode(qr, {
            text: "{{ route('sales.show', $sale->id) }}",
            width: 128,
            height: 128,
            colorDark: "#000",
            colorLight: "#fff",
            correctLevel: QRCode.CorrectLevel.H
        });
    }
});
</script>
